import { useState, useEffect } from 'react'
import { Box, Button, Loader, Stack, Text } from '@mantine/core'
import ClippedPath from '../ClippedPath'
import DetailPanel from '../DetailPanel'
import DriveFolderPickerModal from './DriveFolderPickerModal'
import DriveThumbnailPanel from './ThumbnailPanel'
import GroupNode from './GroupNode'
import FileList from './FileList'
import ResizableLeftPanel from './ResizableLeftPanel'
import { useFileTree, LocalFile } from './useFileTree'
import { useDriveAssignments, DriveAssignment, PickerTarget } from './useDriveAssignments'
import * as pageCache from '../../lib/pageCache'

export default function DriveUploadMode() {
  const { root, tree, loading, error, pickRoot } = useFileTree()
  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0

  const [selectedFile, setSelectedFile] = useState<LocalFile | null>(null)
  const [selectedPage, setSelectedPage] = useState(1)
  const handleSelectFile = (file: LocalFile) => {
    setSelectedFile(file)
    setSelectedPage(1)
  }

  useEffect(() => {
    return () => { if (selectedFile) pageCache.evict(selectedFile.path) }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedFile?.path])

  // Groups start expanded; presence in this set (keyed by the group's full
  // path, e.g. "invoices/2026") means collapsed.
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
  const toggleGroup = (groupKey: string) => {
    setCollapsedGroups(prev => {
      const next = new Set(prev)
      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
      return next
    })
  }

  const assignments = useDriveAssignments()
  const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
  const handlePicked = (folder: DriveAssignment) => {
    if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
    else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
    setPickerTarget(null)
  }

  return (
    <ResizableLeftPanel
      left={
        <>
          <Box mb="sm">
            <ClippedPath path={root} onClick={pickRoot} placeholder="Choose root folder…" />
          </Box>

          <DriveFolderPickerModal
            opened={pickerTarget !== null}
            onClose={() => setPickerTarget(null)}
            onSelect={handlePicked}
          />

          {loading && <Loader size="sm" />}
          {error && <Text size="sm" c="red">{error}</Text>}
          {!loading && !error && isEmpty && (
            <Text size="sm" c="dimmed">No PDF files found under this folder.</Text>
          )}
          {!loading && !root && (
            <Button size="xs" onClick={pickRoot}>Choose Root Folder</Button>
          )}

          {tree && (
            <Stack gap="md" mt="sm">
              {tree.subgroups.map(group => (
                <GroupNode
                  key={group.name}
                  group={group}
                  groupKey={group.name}
                  collapsedGroups={collapsedGroups}
                  onToggle={toggleGroup}
                  assignments={assignments}
                  inheritedAssignment={null}
                  onPick={setPickerTarget}
                  selectedPath={selectedFile?.path ?? null}
                  onSelectFile={handleSelectFile}
                />
              ))}
              <FileList
                files={tree.files}
                assignments={assignments}
                inheritedAssignment={null}
                onPick={setPickerTarget}
                selectedPath={selectedFile?.path ?? null}
                onSelectFile={handleSelectFile}
              />
            </Stack>
          )}
        </>
      }
    >
      <DriveThumbnailPanel
        pdfPath={selectedFile?.path ?? null}
        pageCount={selectedFile?.pageCount ?? 0}
        selectedPage={selectedPage}
        onSelectPage={setSelectedPage}
      />

      {selectedFile
        ? <DetailPanel pdfPath={selectedFile.path} pageNum={selectedPage} pageCount={selectedFile.pageCount} />
        : <Box style={{ flex: 1, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }} />}
    </ResizableLeftPanel>
  )
}

package main

import (
	"os"
	"path/filepath"
	"strings"
)

// LocalFile describes one local PDF discovered by scanLocalRoot.
type LocalFile struct {
	Path      string `json:"path"`
	Name      string `json:"name"` // filename including extension
	SizeBytes int64  `json:"sizeBytes"`
	PageCount int    `json:"pageCount"`
	Corrupt   bool   `json:"corrupt"` // true if the file's page count could not be read
}

// LocalFileGroup is one folder's worth of files, plus its nested
// subfolders. Name is "" only for the root LocalFileGroup returned by
// scanLocalRoot; every subgroup has a real folder name.
type LocalFileGroup struct {
	Name      string           `json:"name"`
	Files     []LocalFile      `json:"files"`
	Subgroups []LocalFileGroup `json:"subgroups"`
}

// scanLocalRoot scans root recursively and returns it as a LocalFileGroup:
// its own direct PDFs in Files, and every subdirectory (at any depth) as a
// nested Subgroups entry. Unlike a subfolder, the root is always returned
// even if it's entirely empty, so the UI has something to render a "no
// files" state from.
func scanLocalRoot(root string) (LocalFileGroup, error) {
	return scanDirectory(root, "")
}

// scanDirectory scans dir's direct entries in a single pass: each PDF
// becomes a LocalFile, each non-hidden subdirectory is scanned recursively
// (skipping symlinks) and — if its subtree contains no PDFs at all — is
// omitted from Subgroups. name is used as the returned group's Name (pass ""
// for the scan root). Files whose page count can't be read (corrupt or
// non-PDF despite the extension) are still included, flagged via
// LocalFile.Corrupt, rather than dropped from the scan.
//
// Both slice fields are always initialized to non-nil (even when empty),
// since a nil Go slice marshals to JSON `null` rather than `[]`, which
// crashes the frontend (e.g. `group.subgroups.length` throws on null).
func scanDirectory(dir, name string) (LocalFileGroup, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return LocalFileGroup{}, err
	}

	files := []LocalFile{}
	subgroups := []LocalFileGroup{}

	for _, e := range entries {
		entryName := e.Name()
		if strings.HasPrefix(entryName, ".") {
			continue
		}

		if e.IsDir() {
			// os.DirEntry.IsDir() reflects the directory entry itself rather
			// than a resolved symlink target, so a symlinked directory
			// (including one that would otherwise form a loop) never enters
			// this branch — it's simply skipped.
			sub, err := scanDirectory(filepath.Join(dir, entryName), entryName)
			if err != nil {
				return LocalFileGroup{}, err
			}
			if len(sub.Files) > 0 || len(sub.Subgroups) > 0 {
				subgroups = append(subgroups, sub)
			}
			continue
		}

		if !strings.HasSuffix(strings.ToLower(entryName), ".pdf") {
			continue
		}
		path := filepath.Join(dir, entryName)
		info, err := os.Stat(path)
		if err != nil {
			continue
		}
		count, err := pdfPageCount(path)
		files = append(files, LocalFile{
			Path:      path,
			Name:      entryName,
			SizeBytes: info.Size(),
			PageCount: count,
			Corrupt:   err != nil, // corrupt or non-PDF despite the extension
		})
	}

	return LocalFileGroup{Name: name, Files: files, Subgroups: subgroups}, nil
}

